const results = $json.organic_results || [];
const targets = [];


const blacklist = [
  'google.com', 
  'youtube.com', 
  'play.google.com', 
  'apple.com', 
  'trustpilot.com', 
  'wikipedia.org'
];

for (let item of results) {

  if (item.position > 10) break; 


  if (targets.length === 3) break;

  const url = item.link;


  const isBlacklisted = blacklist.some(domain => url.includes(domain));

  if (!isBlacklisted) {
    targets.push({
      position: item.position,
      title: item.title,
      link: url
    });
  }
}


return { 
  keyword: $node["Get row(s) in sheet"].json.Keyword,
  geo: $node["Get row(s) in sheet"].json.GEO,
  language: $node["Get row(s) in sheet"].json.Language,
  competitors: targets 
};

const items = $input.all(); // Данные, пришедшие из HTTP Request (HTML или ошибки)
const originalItems = $("Split Out").all(); // Заглядываем назад в Split Out за оригинальными данными
const processedItems = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const orig = originalItems[i].json; // Берем сохраненные данные: keyword, geo и т.д.

  // Восстанавливаем потерянные колонки
  const competitorsData = orig.competitors || {};
  const baseData = {
    keyword: orig.keyword || '',
    geo: orig.geo || '',
    language: orig.language || '',
    position: competitorsData.position || '',
    competitor_title: competitorsData.title || '',
    link: competitorsData.link || ''
  };

  // Пытаемся найти HTML-код (n8n может прятать его в разных свойствах)
  let html = '';
  if (typeof item.json === 'string') {
    html = item.json;
  } else {
    html = item.json.data || item.text || JSON.stringify(item.json) || '';
  }

  // Проверяем, не вернул ли узел ошибку
  const hasError = item.json.error || html.includes('Error') || html.length < 100;

  if (hasError || !html) {
    processedItems.push({
      json: {
        ...baseData,
        h1: 'Ошибка парсинга',
        meta_title: 'Ошибка парсинга',
        meta_description: 'Ошибка парсинга'
      }
    });
    continue;
  }

  // 1. Вытаскиваем <title>
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const meta_title = titleMatch ? titleMatch[1].trim() : 'Не найден';

  // 2. Вытаскиваем Description
  const descMatch = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([\s\S]*?)["']/i) || 
                    html.match(/<meta[^>]+content=["']([\s\S]*?)["'][^>]+name=["']description["']/i);
  const meta_description = descMatch ? descMatch[1].trim() : 'Не найден';

  // 3. Вытаскиваем H1
  const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  const h1 = h1Match ? h1Match[1].replace(/<[^>]*>/g, '').trim() : 'Не найден';

  processedItems.push({
    json: {
      ...baseData,
      h1: h1 || 'Не найден',
      meta_title: meta_title || 'Не найден',
      meta_description: meta_description || 'Не найден'
    }
  });
}

return processedItems;

