const aiItems = $('Basic LLM Chain').all(); // берём AI ответы по имени
const origItems = $('Code in JavaScript1').all(); // оригинальные данные

const groups = {};

for (let i = 0; i < origItems.length; i++) {
  const orig = origItems[i].json;
  const aiText = aiItems[i] ? (aiItems[i].json.text || "") : "";

  let ai_h1 = "", ai_meta_title = "", ai_meta_description = "";
  try {
    const clean = aiText.replace(/```json|```/g, "").trim();
    const parsed = JSON.parse(clean);
    ai_h1 = parsed.h1 || "";
    ai_meta_title = parsed.meta_title || "";
    ai_meta_description = parsed.meta_description || "";
  } catch(e) {}

  const key = (orig.keyword || "") + '|' + (orig.geo || "");

  if (!groups[key]) {
    groups[key] = {
      keyword: orig.keyword,
      geo: orig.geo,
      language: orig.language,
      ai_h1, ai_meta_title, ai_meta_description,
      competitors: []
    };
  }

  groups[key].competitors.push({
    position: orig.position,
    link: orig.link,
    competitor_title: orig.competitor_title,
    scraped_h1: orig.h1,
    scraped_meta_title: orig.meta_title,
    scraped_meta_description: orig.meta_description
  });
}

return Object.values(groups).map(g => ({ json: g }));

